INSERT INTO roadmap_stages (name, order_index, description) VALUES
('Stage 1: Reach Lv50-56 & Unlock Regions', 1, 'Follow the Balenos -> Serendia -> Calpheon -> Mediah main questlines, unlock regional Adventure Logs, reach Succession/Awakening eligibility at level 56.'),
('Stage 2: Life Skill Setup', 2, 'Acquire basic life tools (fishing rod, gathering tools, hunting rifle), key costumes, and start passive knowledge/energy gathering.'),
('Stage 3: Trade Ship & Sailing', 3, 'Unlock Epheria Wharf, build first Epheria Sailboat, progress toward Caravel (trading) or Frigate/Galleass (combat), start barter and deep-sea fishing runs.'),
('Stage 4: Grind Spot Progression', 4, 'Progress through leveling and money grind spots by AP/DP bracket (Sausan Garrison -> Pila Ku/Sycrakea -> Crescent Shrine/Hystria -> Aakman/Manshaum), plus dedicated hunting-zone runs for hides/horns.'),
('Stage 5: Knowledge & Quest Cleanup', 5, 'Complete remaining Adventure Log entries, run the Simplified Questline if applicable, finish Valencia main questline, mop up sub-story knowledge for max energy.'),
('Stage 6: Endgame Prep', 6, 'Begin Tuvala/PEN gear progression, evaluate Carrack ship line, plan Kamasylvia/Drieghan/O''draxxia region unlocks.');
